class Solution:
    def assignElements(self, groups, elements):
        mx = max(groups)
        INF = len(elements)

        # first index of each distinct element value
        first = {}
        for j, v in enumerate(elements):
            if v not in first:
                first[v] = j

        # best[x] = smallest index of an element value that divides x
        best = [INF] * (mx + 1)
        for v, j in first.items():
            for x in range(v, mx + 1, v):
                if j < best[x]:
                    best[x] = j

        return [best[g] if best[g] < INF else -1 for g in groups]
